package com.shopsphere.listener;import jakarta.servlet.*;import jakarta.servlet.annotation.WebListener;@WebListener public class AppListener implements ServletContextListener{public void contextInitialized(ServletContextEvent e){e.getServletContext().setAttribute("appName","ShopSphere");System.out.println("ShopSphere started");}public void contextDestroyed(ServletContextEvent e){System.out.println("ShopSphere stopped");}}
